let language = 'bn';
let step = 0;
let complete = false;
const answers = [null, null];
let draft = '';
let selection = null;
let revision = '';
let trainerNote = '';
let trainerVerdict = 'pending';
let nextCase = 'transfer';
let nextMessage = null;
let submitting = false;
let historyLoad = 0;
let pendingSubmission = null;
const attempts = [null, null];
const exercise = document.querySelector('#exercise');
const text = key => copy[language][key];

function make(tag, className, content) {
 const element = document.createElement(tag);
 if (className) element.className = className;
 if (content !== undefined) element.textContent = content;
 return element;
}
function action(label, handler, secondary = false) {
 const button = make('button', secondary ? 'button secondary' : 'button', text(label));
 button.type = 'button';
 button.onclick = handler;
 return button;
}
function answerText(answer, index) {
 return answer.option === 3 ? answer.value : text('options')[index][answer.option][0];
}
function feedback(answer, index) {
 if (answer.option === 3) return [text('humanRule'), text('humanText')];
 return text('options')[index][answer.option].slice(1);
}
function showFeedback(answer, index) {
 if (attempts[index]) return renderAssessment(attempts[index]);
 const box = make('div', 'feedback-box');
 const [rule, explanation] = feedback(answer, index);
 box.append(make('b', '', rule), make('p', '', explanation));
 return box;
}
function advance() {
 selection = null;
 draft = '';
 renderExercise();
 exercise.tabIndex = -1;
 exercise.focus();
}
function choose(index) {
 const sender = make('div', 'customer-row');
 sender.append(make('span', 'avatar', language === 'bn' ? 'ম' : 'M'), make('b', '', text('customer')));
 const group = make('fieldset', 'answer-group');
 group.append(make('legend', '', text('answerLegend')));
 const own = make('textarea');
 own.setAttribute('aria-label', text('own'));
 own.placeholder = text('placeholder');
 own.maxLength = 1500;
 own.value = draft;
 own.hidden = selection !== 3;
 own.oninput = () => { draft = own.value; };
 const options = index === 1 && nextCase !== 'transfer'
  ? [text('own')]
  : [...text('options')[index].map(option => option[0]), text('own')];
 options.forEach((option, position) => {
  const number = index === 1 && nextCase !== 'transfer' ? 3 : position;
  const label = make('label', 'choice');
  const input = make('input');
  input.type = 'radio';
  input.name = 'answer';
  input.value = number;
  input.checked = selection === number;
  input.onchange = () => {
   selection = number;
   own.hidden = number !== 3;
   if (number === 3) own.focus();
  };
  label.append(input, make('span', '', option));
  group.append(label);
 });
 const error = make('p', 'error');
 error.setAttribute('role', 'alert');
 const actions = make('div', 'actions');
 actions.append(action(index ? 'finalSubmit' : 'submit', async () => {
  if (submitting) return;
  if (selection === null || (selection === 3 && !draft.trim())) {
   error.textContent = text('required');
   return;
  }
  const answer = {option: selection, value: draft.trim()};
  const responseText = answerText(answer, index);
  const caseId = index ? nextCase : 'initial';
  const signature = caseId + responseText;
  if (!pendingSubmission || pendingSubmission.signature !== signature) {
   pendingSubmission = {signature, id: crypto.randomUUID()};
  }
  submitting = true;
  const submitButton = actions.querySelector('button');
  submitButton.disabled = true;
  error.textContent = language === 'bn' ? 'উত্তর যাচাই করা হচ্ছে…' : 'Checking your response…';
  try {
   const response = await fetch('/api/assess', {
    method: 'POST', headers: {'Content-Type':'application/json'},
    body: JSON.stringify({id:pendingSubmission.id, case_id:caseId, answer:responseText}),
    signal: AbortSignal.timeout(20000)
   });
   if (!response.ok) throw new Error('Assessment unavailable');
   const result = await response.json();
   answers[index] = answer;
   attempts[index] = result;
   pendingSubmission = null;
   if (!index) {
    nextCase = result.assessment.next_case;
    nextMessage = result.assessment.next_message;
    step = 1;
   } else complete = true;
   advance();
  } catch {
   error.textContent = language === 'bn'
    ? 'সার্ভারে উত্তর সংরক্ষণ করা যায়নি। আপনার লেখা আছে, আবার চেষ্টা করুন।'
    : 'The response could not be saved. Your draft is here; please try again.';
  } finally {
   submitting = false;
   submitButton.disabled = false;
  }
 }));

 exercise.append(sender, make('p', 'bubble', index && nextMessage ? nextMessage[language] : text(index ? 'case2' : 'case1')), group, own, error, actions);
}
function revise() {
 exercise.append(make('h2', '', text('feedbackTitle')), make('p', 'bubble', answerText(answers[0], 0)), showFeedback(answers[0], 0));
 const label = make('label', '', text('revisionLabel'));
 label.htmlFor = 'revision';
 const input = make('textarea');
 input.id = 'revision';
 input.maxLength = 1500;
 input.placeholder = text('revisionPlaceholder');
 input.value = revision;
 input.oninput = () => { revision = input.value; };
 const error = make('p', 'error');
 error.setAttribute('role', 'alert');
 const actions = make('div', 'actions');
 actions.append(action('revise', async () => {
  if (submitting) return;
  if (!revision.trim()) {error.textContent = text('revisionRequired'); return;}
  submitting = true;
  const button = actions.querySelector('button');
  button.disabled = true;
  try {
   const response = await fetch('/api/revision', {
    method:'POST', headers:{'Content-Type':'application/json'},
    body:JSON.stringify({id:attempts[0].id,revision:revision.trim()}),
    signal:AbortSignal.timeout(20000)
   });
   if(!response.ok) throw new Error('Save failed');
   step=2; advance();
  } catch {
   error.textContent=language==='bn'?'সংশোধন রাখা যায়নি। আবার চেষ্টা করুন।':'Could not save your revision. Please retry.';
  } finally {submitting=false;button.disabled=false;}
 }), action('skip', () => {if(submitting)return; revision = ''; step = 2; advance();}, true));
 exercise.append(label, input, error, actions);
}
function results() {
 exercise.append(make('p', 'outcome', text('resultNote')), make('h2', '', text('result')), make('p', 'bubble', answerText(answers[1], 1)), showFeedback(answers[1], 1));
 const history = make('details');
 history.append(make('summary', '', text('history')), make('p', '', text('before') + ' · ' + answerText(answers[0], 0)), make('p', '', revision ? text('after') + ' · ' + revision : text('kept')));
 const trainer = make('details');
 trainer.append(make('summary', '', text('trainer')));
 const input = make('textarea');
 input.setAttribute('aria-label', text('trainer'));
 input.maxLength = 1500;
 input.placeholder = text('trainerPlaceholder');
 input.value = trainerNote;
 input.oninput = () => {trainerNote = input.value;};
 const status = make('p', 'status');
 status.setAttribute('role', 'status');
 const verdict = make('select');
 verdict.setAttribute('aria-label', language === 'bn' ? 'প্রশিক্ষকের সিদ্ধান্ত' : 'Trainer decision');
 const labels = language === 'bn' ? ['পর্যালোচনা বাকি','আরও অনুশীলন দরকার','এই কেসে প্রস্তুত'] : ['Pending review','Needs practice','Ready for this case'];
 ['pending','needs_practice','ready'].forEach((value, index) => {
  const option = make('option','',labels[index]); option.value=value; verdict.append(option);
 });
 verdict.value=trainerVerdict;
 verdict.onchange=()=>{trainerVerdict=verdict.value;};
 const saveButton = action('save', async () => {
  if (!trainerNote.trim()) {status.textContent=text('emptyNote'); return;}
  saveButton.disabled=true;
  try {
   const response=await fetch('/api/review', {
    method:'POST',headers:{'Content-Type':'application/json'},
    body:JSON.stringify({id:attempts[1].id,note:trainerNote,verdict:verdict.value}),
    signal:AbortSignal.timeout(20000)
   });
   if(!response.ok) throw new Error('Save failed');
   status.textContent=language==='bn'?'পর্যালোচনা সংরক্ষিত হয়েছে।':'Review saved.';
  } catch {status.textContent=language==='bn'?'সংরক্ষণ হয়নি। আবার চেষ্টা করুন।':'Not saved. Please retry.';}
  finally {saveButton.disabled=false;}
 },true);
 trainer.append(input, verdict, saveButton, status);
 const actions = make('div', 'actions');
 actions.append(action('reset', () => {
  step = 0; complete = false; answers.fill(null); attempts.fill(null);
  nextCase = 'transfer'; nextMessage = null; revision = ''; trainerNote = ''; trainerVerdict='pending'; advance();
 }));
 exercise.append(history, trainer, actions);
}
function renderExercise() {
 exercise.replaceChildren();
 document.querySelectorAll('.progress li').forEach((item, index) => {
  item.classList.toggle('active', index === step);
  if (index === step) item.setAttribute('aria-current', 'step');
  else item.removeAttribute('aria-current');
 });
 if (complete) results();
 else if (step === 1) revise();
 else choose(step === 2 ? 1 : 0);
}
function renderLanguage() {
 if (submitting) return;
 document.documentElement.lang = language;
 document.querySelectorAll('[data-copy]').forEach(element => {
  element.textContent = text(element.dataset.copy);
 });
 document.querySelector('#language').textContent = language === 'bn' ? 'English' : 'বাংলা';
 document.querySelector('#history-link').textContent=language==='bn'?'আমার কাজ':'My practice';
 if(location.hash==='#history')loadHistory();
 renderExercise();
}
function route() {
 const practicing = location.hash === '#practice';
 document.querySelector('#home-view').hidden = practicing;
 document.querySelector('#practice-view').hidden = !practicing;
 const historyPage = location.hash === '#history';
 document.querySelector('#history-view').hidden = !historyPage;
 if (historyPage) {
  document.querySelector('#home-view').hidden = true;
  loadHistory();
 }
 if (location.hash === '#how') document.querySelector('#how').scrollIntoView();
 else window.scrollTo(0, 0);
}
document.querySelector('#language').onclick = () => {
 if (submitting) return;
 language = language === 'bn' ? 'en' : 'bn';
 renderLanguage();
};
window.addEventListener('hashchange', route);
renderLanguage();
route();

// Retrieve versioned policy evidence through SIRA's validated result contract.
async function loadPolicyEvidence() {
 const panel = document.querySelector('.policy-panel');
 const old = panel.querySelector('.core-status');
 if (old) old.remove();
 const status = make('p', 'method core-status');
 panel.append(status);
 try {
  const response = await fetch('/api/policy', {cache:'no-store'});
  if (!response.ok) throw new Error('Policy unavailable');
  const payload = await response.json();
  if (payload.result?.status !== 'completed' || payload.result.records.length !== 3) {
   throw new Error('Invalid policy response');
  }
  panel.querySelectorAll('.policy-rule p').forEach((paragraph,index) => {
   paragraph.textContent = payload.result.records[index][language];
  });
  status.textContent = language === 'bn'
   ? 'নীতি সংস্করণ · ' + payload.policy_version + ' · সার্ভার থেকে পাওয়া'
   : 'Policy version · ' + payload.policy_version + ' · retrieved from server';
 } catch {
  status.textContent = language === 'bn'
   ? 'স্থানীয় নমুনা নীতি দেখানো হচ্ছে। সার্ভারের সঙ্গে সংযোগ পাওয়া যায়নি।'
   : 'Showing the bundled sample policy. The server is unavailable.';
 }
}
const previousLanguageHandler = document.querySelector('#language').onclick;
document.querySelector('#language').onclick = () => {
 previousLanguageHandler();
 loadPolicyEvidence();
};
loadPolicyEvidence();

function renderAssessment(attempt) {
 const box = make('div','assessment');
 const assessment = attempt.assessment;
 box.append(make('p','outcome',language==='bn'
  ? 'প্রাথমিক পর্যবেক্ষণ · প্রশিক্ষকের যাচাই প্রয়োজন'
  : 'Preliminary observations · trainer review required'));
 box.append(make('p','meta', 'SIRA · '+assessment.policy_version));
 const modes = language==='bn'
  ? {ai:'এআইয়ের প্রাথমিক বিশ্লেষণ · উদ্ধৃতি মিলিয়ে দেখা হয়েছে',local:'স্থানীয় নিয়মে প্রাথমিক পর্যবেক্ষণ',fallback:'এআই বিশ্লেষণ পাওয়া যায়নি। স্থানীয় নিয়মে প্রাথমিক পর্যবেক্ষণ দেখানো হচ্ছে।'}
  : {ai:'Provisional AI analysis · quotes checked',local:'Preliminary local rule observations',fallback:'AI analysis unavailable. Showing preliminary local rule observations.'};
 box.append(make('p','method',modes[assessment.review_mode || 'local'] || modes.local));
 if (!assessment.findings.length) {
  box.append(make('p','',language==='bn'
   ? 'এই ভাষায় নির্দিষ্ট ইঙ্গিত পাওয়া যায়নি। প্রশিক্ষক সম্পূর্ণ উত্তর দেখবেন।'
   : 'No specific cues were detected in this wording. A trainer will review the full response.'));
 }
 assessment.findings.forEach(finding => {
  const item=make('div','feedback-box');
  if(finding.quote) item.append(make('blockquote','',finding.quote));
  item.append(make('p','',finding.explanation[language]));
  const evidence=make('details');
  evidence.append(make('summary','', (language==='bn'?'নীতির ধারা ':'Policy clause ')+finding.clause));
  evidence.append(make('p','',finding.policy[language]));
  item.append(evidence);box.append(item);
 });
 box.append(make('p','method',assessment.recommendation_reason[language]));
 return box;
}

async function loadHistory() {
 const loadId = ++historyLoad;
 const target=document.querySelector('#history-content');
 target.replaceChildren(make('h1','',language==='bn'?'আপনার কাজের নথি':'Your practice history'));
 try {
  const response=await fetch('/api/history',{signal:AbortSignal.timeout(10000)});
  if(!response.ok)throw new Error('Unavailable');
  const {attempts:history}=await response.json();
  if(loadId !== historyLoad) return;
  if(!history.length) target.append(make('p','',language==='bn'?'প্রথম অনুশীলন শেষ হলে এখানে আপনার উত্তর দেখা যাবে।':'Your responses will appear here after your first practice.'));
  for(const attempt of history){
   const card=make('article','practice-card history-card');
   card.append(make('p','meta',attempt.created+' UTC · '+attempt.assessment.policy_version));
   if(attempt.assessment.case_message) {
    card.append(make('b','',text('customer')),make('p','',attempt.assessment.case_message[language]));
   }
   card.append(make('p','bubble',attempt.answer));
   if(attempt.revision) {
    card.append(make('b','',text('after')),make('p','',attempt.revision));
   }
   const verdicts={pending:['পর্যালোচনা বাকি','Review pending'],ready:['প্রশিক্ষকের মতে এই কেসে প্রস্তুত','Trainer marked ready for this case'],needs_practice:['প্রশিক্ষকের মতে আরও অনুশীলন দরকার','Trainer recommends more practice']};
   card.append(make('p','outcome',verdicts[attempt.verdict][language==='bn'?0:1]));
   const details=make('details');
   details.append(make('summary','',language==='bn'?'উত্তরের প্রমাণ ও পর্যবেক্ষণ':'Evidence and observations'),renderAssessment(attempt));
   card.append(details);
   if(attempt.note)card.append(make('p','',attempt.note));
   target.append(card);
  }
 } catch {if(loadId !== historyLoad) return; target.append(make('p','error',language==='bn'?'ইতিহাস পাওয়া যায়নি। সার্ভারের সংযোগ যাচাই করুন।':'History unavailable. Check the server connection.'));}
 const back=make('a','button',language==='bn'?'অনুশীলনে ফিরুন':'Return to practice');
 back.href='#practice';target.append(back);
}

